window.ROADMAP_DATA['icab-p1'] = {"id":"icab-p1","title":"ICAB P1 - Financial Accounting and Reporting","paperCode":"P1","level":"Professional Level","marks":100,"duration":"3.0 Hours","format":"Written & Scenario-Based Technical Examination","region":"Bangladesh","category":"Professional Level Papers","tags":["Professional Level","Core Exam","Study Tracker","IFRS","Consolidation","Reporting"],"summary":"Advanced preparation, presentation, analysis, and interpretation of single entity and consolidated financial statements under IFRS/BFRS, including Islamic finance and public sector transition.","parentRoadmap":{"id":"icab","label":"ICAB CA Curriculum (2025)","returnHash":"icab-grad","nodeId":"p1"},"defaultRoute":"all","routes":{"all":{"id":"all","name":"Full Syllabus Tracker","default":true,"blurb":"Official 2025 Syllabus chapter and topic tracker for Financial Accounting and Reporting. Track your study progress across all syllabus areas.","stages":[{"id":"p1-s1","title":"Area 1: Accounting & Reporting Concepts and Ethics","name":"Area 1: Accounting & Reporting Concepts and Ethics","weightage":"10%","description":"Standard setting, Conceptual Framework, IAS 8 changes in policy/estimates, and professional ethics.","nodes":[{"id":"p1-s1-n1","name":"IFRS Conceptual Framework & IAS 8","code":"P1.1.1","category":"Standards & Theory","weightage":"10%","description":"Standard-setting process by IASB, FRC Bangladesh endorsement; qualitative characteristics; IAS 8 accounting policies, changes in estimates and prior period errors; ethical dilemmas in financial reporting.","topics":["IASB and FRC standard-setting governance and adoption","IFRS Conceptual Framework: Recognition, measurement bases (historical cost, fair value, value in use)","IAS 8: Retrospective application of policy changes vs prospective estimates","Correction of material prior period errors","Professional ethics under IESBA Code when facing management pressure to misstate"],"learningOutcomes":["Evaluate accounting policies under IAS 8.","Apply IFRS measurement bases.","Resolve ethical conflicts in financial reporting."],"checklists":["Review IAS 8 retrospective restatement steps","Practice disclosure notes for accounting policy changes"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p1-s2","title":"Area 2: Single Entity Financial Statements (IFRS/BFRS)","name":"Area 2: Single Entity Financial Statements (IFRS/BFRS)","weightage":"30%","description":"Preparation of single entity statements applying IAS 16, IAS 36, IAS 38, IAS 37, IFRS 15, IFRS 16, IAS 12.","nodes":[{"id":"p1-s2-n1","name":"Non-Current Assets: IAS 16, IAS 38, IAS 36 & IAS 40","code":"P1.2.1","category":"Standards & Practice","weightage":"15%","description":"PPE revaluation and component depreciation (IAS 16); Intangible assets and R&D capitalization (IAS 38); Impairment testing and CGUs (IAS 36); Investment property fair value vs cost models (IAS 40); Borrowing costs (IAS 23).","topics":["IAS 16 Revaluation model and revaluation surplus accounting","IAS 38 Criteria for capitalizing development expenditure vs research expense","IAS 36 Impairment indicators, Cash Generating Units (CGUs), impairment allocation","IAS 40 Investment Property: Dual-use property, transfers, and fair value model","IAS 23 Capitalization of borrowing costs on qualifying assets"],"learningOutcomes":["Compute revaluations and impairment losses.","Account for intangible assets and investment properties.","Prepare non-current asset note disclosures."],"checklists":["Practice 3 CGU impairment allocation problems","Review IAS 38 development capitalization criteria"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]},{"id":"p1-s2-n2","name":"Revenue, Leases, Provisions & Tax: IFRS 15, IFRS 16, IAS 37, IAS 12","code":"P1.2.2","category":"Standards & Practice","weightage":"15%","description":"IFRS 15 5-step revenue recognition; IFRS 16 Right-of-Use assets and lease liabilities; IAS 37 Provisions and contingent liabilities; IAS 12 Deferred tax temporary differences.","topics":["IFRS 15 5-step model: Contract, performance obligations, transaction price, allocation, satisfaction","IFRS 16 Lessee accounting: ROU asset, lease liability, short-term lease exemptions","IAS 37 Present legal/constructive obligation, probable outflow, reliable estimate","IAS 37 Restructuring provisions, onerous contracts, contingent assets/liabilities","IAS 12 Deferred tax: Tax base vs carrying amount, taxable vs deductible temporary differences"],"learningOutcomes":["Apply 5-step model to multi-element revenue contracts.","Account for leases under IFRS 16.","Compute deferred tax provisions and prepare reconciliation."],"checklists":["Complete 3 full IFRS 15 multi-element revenue calculations","Calculate deferred tax on revalued assets under IAS 12"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p1-s3","title":"Area 3: Consolidated Financial Statements","name":"Area 3: Consolidated Financial Statements","weightage":"30%","description":"Group accounting under IFRS 10, IFRS 3, and IAS 28; subsidiaries, associates, and intra-group adjustments.","nodes":[{"id":"p1-s3-n1","name":"Consolidated Statement of Financial Position (IFRS 10 & IFRS 3)","code":"P1.3.1","category":"Group Accounting","weightage":"15%","description":"Concept of control under IFRS 10; goodwill computation under IFRS 3 (proportionate vs fair value method); non-controlling interests (NCI); intra-group balances, cash-in-transit, and unrealized profit on inventory and PPE.","topics":["IFRS 10 Control model: Power, exposure to variable returns, link between power and returns","Goodwill calculation: Purchase consideration, fair value of net assets, NCI valuation","Fair value adjustments to net assets at acquisition date and subsequent depreciation","Intra-group balances, cash and goods in transit reconciliation","Unrealized profit (PURP) in closing inventory and transfer of PPE between group entities","Consolidated retained earnings and non-controlling interest calculation"],"learningOutcomes":["Calculate goodwill and NCI under IFRS 3.","Eliminate intra-group balances and unrealized profits.","Prepare consolidated statement of financial position."],"checklists":["Draft 3 full consolidated balance sheets with fair value adjustments","Master PURP inventory adjustment for parent vs subsidiary sales"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]},{"id":"p1-s3-n2","name":"Consolidated Profit or Loss & Associates (IAS 28)","code":"P1.3.2","category":"Group Accounting","weightage":"15%","description":"Consolidated Statement of Profit or Loss; mid-year acquisitions; intra-group sales and dividends; NCI share of profit; Equity accounting for associates under IAS 28.","topics":["Consolidated P&L preparation: Revenue, cost of sales, operating expenses line-by-line","Mid-year acquisition: Apportionment of subsidiary revenue and expenses","Elimination of intra-group sales, management fees, interest, and dividends","Allocation of profit for the year between owners of parent and NCI","IAS 28 Accounting for associates: Significant influence test (20-50%), equity method","Equity accounting adjustments: Group share of associate profit, PURP in associate sales"],"learningOutcomes":["Prepare consolidated statement of profit or loss for mid-year acquisition.","Allocate comprehensive income to NCI.","Apply equity method for investments in associates."],"checklists":["Complete 2 mid-year acquisition group P&L questions","Review equity method balance sheet and income statement presentations"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p1-s4","title":"Area 4: Financial Statement Analysis & Interpretation","name":"Area 4: Financial Statement Analysis & Interpretation","weightage":"15%","description":"Financial ratio analysis, statement of cash flows (IAS 7), and performance appraisal.","nodes":[{"id":"p1-s4-n1","name":"Cash Flows (IAS 7) & Comprehensive Ratio Analysis","code":"P1.4.1","category":"Financial Analysis","weightage":"15%","description":"Preparation of Statement of Cash Flows under IAS 7 (indirect method); profitability, liquidity, efficiency, and solvency ratios; limitations of ratio analysis.","topics":["IAS 7 Cash Flows: Operating activities (indirect method), investing, and financing activities","Non-cash transactions, interest, dividend, and tax cash flows","Profitability ratios: ROCE, Gross margin, Net margin, Asset turnover","Liquidity & working capital ratios: Current ratio, Quick ratio, Inventory turnover days, Debtor days","Solvency and gearing: Debt-to-equity, Interest cover","Investor ratios: Earnings per share (IAS 33 basics), P/E ratio, Dividend yield","Limitations of financial statement analysis and qualitative factors"],"learningOutcomes":["Construct IAS 7 statement of cash flows using indirect method.","Compute and interpret financial ratios across multiple periods.","Write an executive report evaluating corporate financial health."],"checklists":["Prepare 2 full IAS 7 cash flow statements with working capital adjustments","Write a 500-word performance critique on profitability vs liquidity"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p1-s5","title":"Area 5: Islamic Finance & Public Sector Accounting","name":"Area 5: Islamic Finance & Public Sector Accounting","weightage":"15%","description":"AAOIFI accounting standards for Islamic financial institutions, and cash-to-accrual public sector transition.","nodes":[{"id":"p1-s5-n1","name":"AAOIFI Islamic Accounting & IPSAS Accrual Transition","code":"P1.5.1","category":"Specialized Accounting","weightage":"15%","description":"Accounting for Islamic financial transactions under AAOIFI standards (Murabaha, Ijara, Mudaraba, Musharaka, Sukuk); transition from cash to accrual accounting in Bangladesh public sector; IPSAS standards.","topics":["Principles of Islamic banking and finance: Riba prohibition, risk sharing, asset-backing","Accounting for Murabaha (cost-plus sale) and Ijara (leasing) contracts under AAOIFI","Mudaraba and Musharaka profit-and-loss sharing mechanisms and balance sheet recognition","Sukuk (Islamic bonds) structure, issuance, and financial reporting","Government financial management in Bangladesh: Move from cash basis to accrual basis","Key IPSAS standards: Fixed assets, financial liabilities, revenue from exchange transactions"],"learningOutcomes":["Record Islamic financing transactions under AAOIFI standards.","Differentiate Murabaha and Ijara accounting treatments.","Explain challenges in transitioning public sector accounting to accruals."],"checklists":["Compare AAOIFI Murabaha accounting with IFRS 9 amortized cost","Summarize 4 key implementation steps of IPSAS in Bangladesh"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]}]}}};
window.ROADMAP_DATA['icab-p2'] = {"id":"icab-p2","title":"ICAB P2 - Audit and Assurance","paperCode":"P2","level":"Professional Level","marks":100,"duration":"3.0 Hours","format":"Written & Scenario-Based Technical Examination","region":"Bangladesh","category":"Professional Level Papers","tags":["Professional Level","Core Exam","Study Tracker","ISA","Audit Risk","Auditor Report"],"summary":"Covers acceptance, managing and performing audit and assurance engagements in accordance with International Standards on Auditing (ISAs), risk assessment, audit evidence, and auditor reporting.","parentRoadmap":{"id":"icab","label":"ICAB CA Curriculum (2025)","returnHash":"icab-grad","nodeId":"p2"},"defaultRoute":"all","routes":{"all":{"id":"all","name":"Full Syllabus Tracker","default":true,"blurb":"Official 2025 Syllabus chapter and topic tracker for Audit and Assurance. Track your study progress across all syllabus areas.","stages":[{"id":"p2-s1","title":"Area 1: Legal/Professional Regulations, Ethics & Acceptance","name":"Area 1: Legal/Professional Regulations, Ethics & Acceptance","weightage":"25%","description":"Statutory audit requirements, IESBA Code of Ethics, quality management (ISQM 1), and client acceptance.","nodes":[{"id":"p2-s1-n1","name":"ISQM 1, Professional Ethics & Client Acceptance","code":"P2.1.1","category":"Ethics & Governance","weightage":"25%","description":"Appointment, removal, and duties of auditors under Companies Act 1994; FRC audit oversight; IESBA Code of Ethics for Professional Accountants; ISQM 1 Quality Management for Firms; client acceptance and engagement management.","topics":["Auditor appointment, qualifications, disqualifications, and removal under Companies Act 1994","Role of Financial Reporting Council (FRC) Bangladesh in auditing oversight","IESBA Code fundamental principles, independence in mind and appearance","Ethical threats (long association, non-audit services, fee dependence) and safeguards","ISQM 1: System of quality management, governance, ethics, risk assessment, monitoring","Pre-conditions for audit (ISA 210), engagement letters, client onboarding and KYC"],"learningOutcomes":["Evaluate compliance with Companies Act 1994 auditor appointment rules.","Design firm quality management procedures under ISQM 1.","Resolve complex independence and conflict of interest scenarios."],"checklists":["Review ISQM 1 eight components checklist","Practice 4 ethical threat scenarios with appropriate safeguards"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p2-s2","title":"Area 2: Planning & Performing Audit Engagements","name":"Area 2: Planning & Performing Audit Engagements","weightage":"50%","description":"Audit risk (ISA 315), materiality (ISA 320), fraud (ISA 240), internal control evaluation, and substantive procedures.","nodes":[{"id":"p2-s2-n1","name":"Audit Risk Assessment & Materiality (ISA 315 & 320)","code":"P2.2.1","category":"Audit Risk & Planning","weightage":"25%","description":"Audit risk model: Inherent risk, Control risk, Detection risk; understanding the entity and environment (ISA 315 Revised); planning and performance materiality (ISA 320); auditor responsibilities for fraud (ISA 240); IT environment risks and automated controls.","topics":["The audit risk model: AR = IR x CR x DR and its practical application","ISA 315 (Revised 2019): Identifying and assessing risks of material misstatement (RMM)","Assessing IT general controls (ITGCs) and automated application controls","Determination of planning materiality, performance materiality, and trivial threshold (ISA 320)","Auditor's responsibilities relating to fraud in an audit (ISA 240): Fraud risk factors and skepticism","Laws and regulations in an audit (ISA 250): Direct vs indirect compliance"],"learningOutcomes":["Calculate planning and performance materiality benchmarks.","Identify and assess risks of material misstatement at financial statement and assertion levels.","Design responses to address identified fraud risks."],"checklists":["Calculate materiality on 3 scenario financial statements","Draft risk and response audit planning matrix"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]},{"id":"p2-s2-n2","name":"Substantive Audit Procedures & Complex Balances","code":"P2.2.2","category":"Substantive Procedures","weightage":"25%","description":"Designing substantive audit tests for complex areas: Revenue (IFRS 15), Inventory, Provisions, Going concern (ISA 570), Related parties (ISA 550), and Accounting estimates (ISA 540).","topics":["Substantive testing methodology: Analytical procedures vs tests of details","Auditing revenue recognition under IFRS 15: Cut-off, rebates, multi-element contracts","Auditing inventory: Count attendance, valuation testing, NRV write-down testing","Auditing accounting estimates including fair value under ISA 540 (Revised)","Auditing related party transactions and disclosures under ISA 550","Going concern evaluation under ISA 570: Indicators, cash forecasts, and management support","Audit sampling techniques (ISA 530) and Computer-Assisted Audit Techniques (CAATs)"],"learningOutcomes":["Design detailed substantive audit programs for high-risk accounts.","Audit complex accounting estimates and fair value measurements.","Evaluate going concern adequacy and audit evidence."],"checklists":["Read Substantive Audit Procedures & Complex Balances in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p2-s3","title":"Area 3: Concluding & Reporting on Engagements","name":"Area 3: Concluding & Reporting on Engagements","weightage":"25%","description":"Subsequent events (ISA 560), written representations (ISA 580), and auditor reporting (ISA 700, 701, 705, 706).","nodes":[{"id":"p2-s3-n1","name":"Subsequent Events, Evaluation & Auditor's Report","code":"P2.3.1","category":"Auditor Reporting","weightage":"25%","description":"Subsequent events up to and after report date (ISA 560); written representations from management (ISA 580); evaluating misstatements (ISA 450); Key Audit Matters (KAM - ISA 701); unmodified vs modified opinions (ISA 705); Emphasis of Matter and Other Matter paragraphs (ISA 706).","topics":["Evaluating uncorrected misstatements against materiality thresholds (ISA 450)","Subsequent events procedures: Adjusting vs non-adjusting events under IAS 10 / ISA 560","Written representations: Purpose, limitations, and refusal to provide (ISA 580)","Standard unmodified auditor's report structure under ISA 700 (Revised)","Communicating Key Audit Matters (KAM) in listed entity reports (ISA 701)","Modifications to the opinion (ISA 705): Qualified, Adverse, Disclaimer of opinion","Emphasis of Matter and Other Matter paragraphs (ISA 706) criteria and placement"],"learningOutcomes":["Determine required modifications to the audit opinion based on pervasive/material tests.","Draft Key Audit Matters (KAM) descriptions for listed entities.","Evaluate the impact of subsequent events on audit reports."],"checklists":["Memorize opinion decision matrix (Material vs Material & Pervasive)","Draft sample Key Audit Matter paragraph for inventory valuation"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]}]}}};
window.ROADMAP_DATA['icab-p3'] = {"id":"icab-p3","title":"ICAB P3 - Business Planning: Taxation & Compliance","paperCode":"P3","level":"Professional Level","marks":100,"duration":"3.0 Hours","format":"Written & Scenario-Based Technical Examination","region":"Bangladesh","category":"Professional Level Papers","tags":["Professional Level","Core Exam","Study Tracker","Tax Planning","Transfer Pricing","VAT Litigation"],"summary":"Advanced corporate taxation, group relief, business restructuring, international taxation, transfer pricing, dispute resolution, tax litigation, and strategic VAT compliance under Bangladesh tax legislation.","parentRoadmap":{"id":"icab","label":"ICAB CA Curriculum (2025)","returnHash":"icab-grad","nodeId":"p3"},"defaultRoute":"all","routes":{"all":{"id":"all","name":"Full Syllabus Tracker","default":true,"blurb":"Official 2025 Syllabus chapter and topic tracker for Business Planning: Taxation & Compliance. Track your study progress across all syllabus areas.","stages":[{"id":"p3-s1","title":"Area 1: Income Tax Administration, Disputes & Transfer Pricing","name":"Area 1: Income Tax Administration, Disputes & Transfer Pricing","weightage":"40%","description":"Tax assessments, audit, appeals to Appellate Tribunal and High Court, ADR, and Transfer Pricing Chapter.","nodes":[{"id":"p3-s1-n1","name":"Tax Litigation, Appeals & Alternative Dispute Resolution (ADR)","code":"P3.1.1","category":"Tax Litigation","weightage":"20%","description":"Selection of cases for tax audit; assessment under Section 180 vs best judgment under Section 182; appeals to Commissioner (Appeals); Taxes Appellate Tribunal; High Court references; Alternative Dispute Resolution (ADR) mechanism.","topics":["Audit selection criteria and powers of Deputy Commissioner of Taxes (DCT)","Reopening of assessment: Section 212 powers and statutory time bars","First appeal to Commissioner of Taxes (Appeals): Grounds, deposit requirements, timelines","Second appeal to Taxes Appellate Tribunal: Composition, procedures, legal questions","Reference applications to High Court Division of the Supreme Court of Bangladesh","Alternative Dispute Resolution (ADR): Eligibility, facilitator role, binding agreement"],"learningOutcomes":["Formulate grounds of appeal for disputed tax assessments.","Advise clients on ADR benefits and dispute resolution strategy.","Draft legal submissions for Taxes Appellate Tribunal."],"checklists":["Review appellate timeline and mandatory tax deposit rules","Study ADR procedural guidelines under ITA 2023"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]},{"id":"p3-s1-n2","name":"Transfer Pricing, International Tax & Double Taxation","code":"P3.1.2","category":"International Tax","weightage":"20%","description":"Arm's length principle; Transfer Pricing methods under ITA 2023 (CUP, Resale Price, Cost Plus, TNMM, Profit Split); TP documentation and accountant certification; Double Taxation Avoidance Agreements (DTAA); permanent establishment (PE).","topics":["Transfer pricing regulations under Bangladesh Income Tax Act 2023","Definition of associated enterprise and international transactions","Arm's length price determination methods: CUP, Resale Price, Cost Plus, Profit Split, TNMM","Transfer pricing documentation requirements and mandatory Chartered Accountant certificate","Double Tax Avoidance Agreements (DTAA): Credit method vs Exemption method","Permanent Establishment (PE) concepts and taxation of cross-border digital services"],"learningOutcomes":["Select and defend the most appropriate transfer pricing method.","Compute tax credits under DTAA provisions.","Identify Permanent Establishment exposure for multinational entities."],"checklists":["Read Transfer Pricing, International Tax & Double Taxation in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p3-s2","title":"Area 2: Corporate Tax Planning & Restructuring","name":"Area 2: Corporate Tax Planning & Restructuring","weightage":"30%","description":"Tax planning for corporate reorganizations, mergers, amalgamations, demergers, and incentives.","nodes":[{"id":"p3-s2-n1","name":"Tax-Efficient Mergers, Acquisitions & Incentives","code":"P3.2.1","category":"Corporate Tax Strategy","weightage":"30%","description":"Tax implications of business combinations, amalgamations, and demergers; carry-forward and set-off of accumulated losses; tax holidays and economic zone incentives (BEZA, BIDA, Hi-Tech parks); tax-efficient financing structures (debt vs equity, thin capitalization).","topics":["Tax treatment of amalgamations and company mergers under ITA 2023","Conditions for transfer of accumulated tax losses and unabsorbed depreciation in mergers","Demergers, slump sales, and asset acquisitions tax implications","Tax holiday regimes for industrial undertakings, physical infrastructure, and green initiatives","Incentives in Special Economic Zones (BEZA) and Hi-Tech Parks","Tax planning for employee remuneration: ESOPs, provident funds, gratuity approvals","Thin capitalization and interest deductibility restrictions"],"learningOutcomes":["Structure tax-neutral corporate amalgamations.","Advise corporations on claiming tax holiday benefits in Economic Zones.","Optimize debt-equity ratios considering tax deductibility."],"checklists":["Read Tax-Efficient Mergers, Acquisitions & Incentives in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p3-s3","title":"Area 3: Strategic VAT Compliance & Customs","name":"Area 3: Strategic VAT Compliance & Customs","weightage":"30%","description":"VAT planning, audits, investigations, appeals, customs valuation, and import-export procedures.","nodes":[{"id":"p3-s3-n1","name":"VAT Audits, Investigations, Appeals & Customs","code":"P3.3.1","category":"Indirect Tax Strategy","weightage":"30%","description":"VAT audits and investigations by Customs, Excise and VAT Commissionerate; demand notices and show-cause proceedings; appeals to Commissioner (Appeals) and Customs, Excise and VAT Appellate Tribunal; customs valuation under Customs Act 2023; bonded warehouse facilities.","topics":["Powers of VAT officers during audits, inspections, and seizure of records","Adjudication process: Show Cause Notice (SCN) response and personal hearings","VAT appellate procedure: Appeal to Commissioner (Appeals), Tribunal, and High Court","Input tax rebate disputes, credit cancellation, and recovery of unpaid VAT","Customs Act 2023: Assessment of customs duty, regulatory duty, and advance tax on imports","Customs valuation methods: Transaction value of imported goods and adjustments","Bonded warehouse facilities, duty drawback, and export facilitation"],"learningOutcomes":["Draft replies to VAT show-cause notices.","Navigate the VAT and Customs appellate ladder.","Optimize customs duty through bonded warehouse and drawback facilities."],"checklists":["Read VAT Audits, Investigations, Appeals & Customs in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]}]}}};
window.ROADMAP_DATA['icab-p4'] = {"id":"icab-p4","title":"ICAB P4 - Financial Management","paperCode":"P4","level":"Professional Level","marks":100,"duration":"3.0 Hours","format":"Written & Quantitative Technical Examination","region":"Bangladesh","category":"Professional Level Papers","tags":["Professional Level","Core Exam","Study Tracker","Corporate Finance","WACC","Valuation","Hedging"],"summary":"Advanced corporate finance, capital structure, cost of capital (WACC), investment appraisal under uncertainty, business valuation, treasury risk management, and ESG finance.","parentRoadmap":{"id":"icab","label":"ICAB CA Curriculum (2025)","returnHash":"icab-grad","nodeId":"p4"},"defaultRoute":"all","routes":{"all":{"id":"all","name":"Full Syllabus Tracker","default":true,"blurb":"Official 2025 Syllabus chapter and topic tracker for Financial Management. Track your study progress across all syllabus areas.","stages":[{"id":"p4-s1","title":"Area 1: Business Finance – Methods & Strategies","name":"Area 1: Business Finance – Methods & Strategies","weightage":"30%","description":"Cost of capital, WACC, capital structure theories (Modigliani-Miller), and dividend policy.","nodes":[{"id":"p4-s1-n1","name":"Cost of Capital (WACC) & Capital Structure Theories","code":"P4.1.1","category":"Corporate Finance","weightage":"30%","description":"Cost of equity using CAPM and Dividend Growth Model; cost of debt (irredeemable, redeemable, convertible); calculation of Weighted Average Cost of Capital (WACC); capital structure theories: Traditional view, Modigliani-Miller with and without corporate taxes, pecking order theory; dividend policy theories and signaling.","topics":["Cost of equity calculation: Capital Asset Pricing Model (CAPM) and Gordon Growth Model","Systematic vs unsystematic risk, Beta estimation, de-gearing and re-gearing betas","Cost of redeemable debt using internal rate of return (IRR) interpolation","Cost of convertible bonds and floor value analysis","Weighted Average Cost of Capital (WACC) calculation and conditions for use in appraisal","Capital structure debate: Traditional view vs MM Proposition I & II (tax shield)","Pecking order hypothesis, trade-off theory, and financial distress costs","Dividend irrelevance (MM) vs Walter/Gordon models, clientele effect, signaling"],"learningOutcomes":["Calculate WACC for complex financing structures.","Evaluate capital structure decisions applying MM theories.","De-gear and re-gear equity betas for investment projects."],"checklists":["Solve 3 complex WACC calculations with convertible debt","Master asset beta formula: Beta_A = Beta_E * (E/(E+D(1-t)))"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p4-s2","title":"Area 2: Investment Appraisal & Business Valuation","name":"Area 2: Investment Appraisal & Business Valuation","weightage":"30%","description":"Discounted cash flow (DCF), sensitivity, real options, M&A, and company valuation methods.","nodes":[{"id":"p4-s2-n1","name":"DCF Appraisal, Risk Analysis & Business Valuation","code":"P4.2.1","category":"Valuation & Investments","weightage":"30%","description":"Net Present Value (NPV), IRR, MIRR, Payback; dealing with inflation, taxation, and capital rationing; sensitivity analysis and simulation; real options (delay, expand, abandon); business valuation methods: Asset-based, Earnings multiples (P/E, EV/EBITDA), Free Cash Flow to Firm (FCFF) and Equity (FCFE).","topics":["NPV analysis incorporating working capital, tax depreciation allowances, and residual values","Inflation in investment appraisal: Real discount rate vs nominal cash flows (Fisher equation)","Single-period capital rationing: Profitability Index (PI) ranking","Multi-period capital rationing and linear programming principles","Risk in investment appraisal: Sensitivity analysis, scenario analysis, real options value","Business valuation approaches: Net Asset Value (NAV), book value vs liquidation value","Earnings-based valuation: P/E multiples, EV/EBITDA, earnings yield method","Discounted Free Cash Flow valuation: FCFF discounted at WACC, FCFE discounted at Ke","Mergers and acquisitions: Valuation of synergies and defense against hostile bids"],"learningOutcomes":["Formulate advanced DCF models with tax shields and capital rationing.","Value private and public companies using FCFF and market multiple methods.","Quantify real options in high-uncertainty capital investments."],"checklists":["Read DCF Appraisal, Risk Analysis & Business Valuation in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p4-s3","title":"Area 3: Treasury & Financial Risk Management","name":"Area 3: Treasury & Financial Risk Management","weightage":"25%","description":"Currency and interest rate risk management using forwards, futures, options, and swaps.","nodes":[{"id":"p4-s3-n1","name":"FX Hedging, Interest Rate Risk & Derivatives","code":"P4.3.1","category":"Risk Management","weightage":"25%","description":"Foreign exchange risk exposure: Transaction, translation, and economic risk; hedging techniques: Forward contracts, money market hedges, futures, currency options, currency swaps; interest rate risk: Forward Rate Agreements (FRAs), interest rate futures, options (caps, floors, collars), interest rate swaps.","topics":["Foreign exchange exposure types: Transaction, translation, economic risk","Internal hedging techniques: Invoicing in home currency, netting, matching, leading/lagging","External FX hedging: Forward contracts vs Money market hedge step-by-step comparison","Currency futures and options hedging: Call vs Put option strategies","Interest rate risk sources: Gap analysis, basis risk","Forward Rate Agreements (FRAs) structure, fixing rates, and settlement calculations","Interest rate swaps: Comparative advantage argument, mechanics, counterparty risk","Options on interest rates: Caps, Floors, Collars construction and cost optimization"],"learningOutcomes":["Construct money market hedges for FX payments and receipts.","Hedge floating interest rate exposure using FRAs and interest rate swaps.","Design option collar strategies to bound interest rate costs."],"checklists":["Read FX Hedging, Interest Rate Risk & Derivatives in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]},{"id":"p4-s4","title":"Area 4: Sustainable Finance, ESG & FinTech","name":"Area 4: Sustainable Finance, ESG & FinTech","weightage":"15%","description":"Green bonds, ESG investment metrics, FinTech innovations, and climate risk finance.","nodes":[{"id":"p4-s4-n1","name":"Green Finance, ESG Integration & Financial Technology","code":"P4.4.1","category":"Emerging Finance","weightage":"15%","description":"Role of sustainable finance and Bangladesh Bank Green Banking Policy; green bonds, sustainability-linked loans (SLL); ESG ratings and investment screening; financial technology (FinTech): Mobile financial services (bKash/Nagad), blockchain in settlement, and crowdfunding.","topics":["Bangladesh Bank Green Banking policy guidelines and mandatory refinancing schemes","Green bonds and sustainability-linked debt: Issuance criteria, verification, greenium","Integrating ESG criteria into corporate cost of capital and DCF valuation","Climate-related financial risks: Physical risks vs transition risks","FinTech ecosystem in Bangladesh: MFS, digital credit, peer-to-peer lending","Blockchain and distributed ledger technology (DLT) in international trade finance and remittances"],"learningOutcomes":["Apply green banking criteria to evaluate project financing proposals.","Explain the pricing and structuring of green bonds in Bangladesh.","Assess FinTech business models and regulatory sandboxes."],"checklists":["Read Green Finance, ESG Integration & Financial Technology in ICAB Study Manual","Complete chapter review practice questions","Review past exam scenario questions"],"resources":["ICAB Study Manual (2025 Edition)","ICAB Latest Syllabus 2025 (Official Document)","Relevant Acts & Standards (IFRS / ISA / Tax Acts)"]}]}]}}};
